const minimum=document.getElementById("dataset-relevance"),search=document.getElementById("dataset-filter"),body=document.querySelector("tbody"),rows=Array.from(body.rows,e=>({row:e,name:e.dataset.names.toLowerCase(),title:e.cells[0].firstElementChild.textContent,count:e.querySelector("[data-paper-count]"),scores:Array.from(e.dataset.scores,Number),size:e.dataset.sizeGb===""?null:Number(e.dataset.sizeGb)})),total=document.getElementById("dataset-size-total"),sizes=new Intl.NumberFormat("en",{useGrouping:!1,minimumFractionDigits:1,maximumFractionDigits:3}),titles=new Intl.Collator("en",{sensitivity:"base"});function filter(){const i=search.value.trim().toLowerCase(),n=minimum.value===""?-1:Number(minimum.value);let e=0,s=0,t=0;for(const a of rows){const{row:r,name:l,count:d,scores:u,size:c}=a,o=u.filter(e=>e>n).length;a.matching=o,d.textContent=o,r.hidden=!l.includes(i)||n>=0&&o===0,r.hidden||(e++,c!==null&&(s+=c,t++))}rows.sort((e,t)=>t.matching-e.matching||titles.compare(e.title,t.title));const o=document.createDocumentFragment();for(const{row:e}of rows)o.append(e);body.replaceChildren(o),total.textContent=t?sizes.format(s):"—",total.title=t+" of "+e+" visible datasets with a listed size",document.getElementById("no-datasets").hidden=e>0}minimum.addEventListener("input",filter),search.addEventListener("input",filter),document.getElementById("filters").hidden=!1,filter()